contract InvMutTest {
    C c;
    uint public beforeCBalance;
    uint public beforeMyBalance;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address callee, bytes calldata _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balances before the call
        beforeCBalance = address(c).balance;
        beforeMyBalance = address(this).balance;

        bool reverted;
        c.forward(callee, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call: if it succeeded (did not revert) then C's balance did not increase
        // and this contract's balance did not increase (i.e., no Ether was magically transferred to test)
        assert(
            reverted || (address(c).balance <= beforeCBalance && address(this).balance <= beforeMyBalance)
        );
    }
    receive() external payable { }
}

